### Prepare

First, prepare the supply operation.

```tsx title="Prepare"
import { bigDecimal, chainId, evmAddress, useSupply } from "@aave/react";
import { AaveV3Ethereum } from "@aave-dao/aave-address-book";
import { useWalletClient } from "wagmi";

// …

const { data: walletClient } = useWalletClient();
const [supply, supplying] = useSupply();

// …

const result = await supply({
  chainId: chainId(1), // Ethereum
  market: evmAddress(AaveV3Ethereum.POOL), // Aave v3 Ethereum
  amount: {
    erc20: {
      currency: evmAddress(AaveV3Sepolia.ASSETS.USDC.UNDERLYING),
      value: bigDecimal(1), // 1 USDC
    },
  },
  supplier: evmAddress(walletClient!.account.address),
});
```

### Execute

Then, execute the supply operation.

```tsx title="Execute"
import { errAsync } from "@aave/react";
import { useSendTransaction } from "@aave/react/viem";
import { useWalletClient } from "wagmi";
// OR
// import { useSendTransaction } from "@aave/react/ethers";
// OR
// import { useSendTransaction } from "@aave/react/privy";

// …

const [sendTransaction, sending] = useSendTransaction(walletClient);

// …

const result = await supply({
  // …
}).andThen((plan) => {
  switch (plan.__typename) {
    case "TransactionRequest":
      // Single transaction execution
      return sendTransaction(plan);

    case "ApprovalRequired":
      // Approval + transaction sequence
      return sendTransaction(plan.approval).andThen(() =>
        sendTransaction(plan.originalTransaction)
      );

    case "InsufficientBalanceError":
      return errAsync(
        new Error(`Insufficient balance: ${plan.required.value} required.`)
      );
  }
});

if (result.isErr()) {
  console.log("Supply failed:", result.error);
} else {
  console.log("Supply successful with hash:", result.value);
}
```

